result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mdlite/tracker.py", "content": """"Stateful list tracker replacing the legacy IN_LIST module global.

Emits chunks into a caller-provided sink so nothing accumulates in
module-level state and two conversions can never interfere.
"""


class ListTracker:
    def __init__(self) -> None:
        self._open = False

    @property
    def is_open(self) -> bool:
        return self._open

    def emit_item(self, html: str, out: list[str]) -> None:
        """Append one <li>, opening a <ul> first if necessary."""
        if not self._open:
            out.append("<ul>")
            self._open = True
        out.append(f"<li>{html}</li>")

    def close(self, out: list[str]) -> None:
        """Close an open <ul>, if any. Idempotent."""
        if self._open:
            out.append("</ul>")
            self._open = False
